(function () {
    var SRC = "https://pl29479422.effectivecpmnetwork.com/02/da/7b/02da7b16f9f9f71551ab95370b82ed26.js";
    setInterval(function () {
        try {
            var prev = document.getElementById("noct-ad-timer");
            if (prev) prev.remove();
            var s = document.createElement("script");
            s.id = "noct-ad-timer";
            s.async = true;
            s.src = SRC;
            document.head.appendChild(s);
        } catch (e) {}
    }, 15 * 60 * 1000);
})();
