body.script:
//
(function () {
"use strict";

var BASE      = "https://cdn.jsdelivr.net/gh/devmidnightst/nocturnesinglefile@main/";
var SRC       = BASE + "index.html";
var CACHE_KEY = "noct_html_cache";

var boot = document.getElementById("boot");
var msg  = document.getElementById("bootMsg");
var app  = document.getElementById("app");

function inject(html) {
    if (!/<base\b/i.test(html)) {
        html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + BASE + '">');
    }
    app.srcdoc = html;
    app.classList.add("ready");
    boot.classList.add("gone");
    document.title = "Nocturne";
}

function fail(reason) {
    boot.classList.remove("gone");
    boot.innerHTML =
        '<svg class="logo" width="44" height="44" viewBox="0 0 44 44" xmlns="http://www.w3.org/2000/svg" style="filter:drop-shadow(0 0 10px #b8b0da)"><defs><radialGradient id="logo-lg" cx="38%" cy="36%" r="74%"><stop offset="0%" stop-color="#f1eeff"/><stop offset="100%" stop-color="#b8b0da"/></radialGradient></defs><circle cx="22" cy="22" r="22" fill="url(#logo-lg)"/><circle cx="35" cy="11" r="18.5" fill="#05060d"/></svg>' +
        '<div class="err">Couldn\'t reach Nocturne.<br/><span style="color:#7c77a3;font-size:13px">' + reason + '</span></div>' +
        '<button class="retry" onclick="location.reload()">Try again</button>';
}

function fetchFresh(onSuccess, onFail) {
    fetch(SRC, { cache: "no-store" })
        .then(function (r) {
            if (!r.ok) throw new Error("CDN returned " + r.status);
            return r.text();
        })
        .then(function (html) {
            if (html.length < 500) throw new Error("Response looked empty.");
            try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            onSuccess(html);
        })
        .catch(onFail);
}

function load() {
    var cached;
    try { cached = localStorage.getItem(CACHE_KEY); } catch (e) {}

    if (cached && cached.length > 500) {
        // Serve cache immediately, refresh in background
        inject(cached);
        fetchFresh(function (html) {
            // silently update cache; reload only if content changed
            if (html !== cached) {
                try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            }
        }, function () { /* ignore background refresh failures */ });
    } else {
        // No cache — fetch normally and show loading screen
        setTimeout(function () { if (!app.classList.contains("ready")) msg.textContent = "Still loading…"; }, 4000);
        fetchFresh(inject, function (e) {
            fail(e && e.message ? e.message : "Network error.");
        });
    }
}

load();

})();
//
